#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    // suffix: p[n-y .. n-1]
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    // middle: p[x .. n-y-1]
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    // prefix: p[0 .. x-1]
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1,2,...,n-2 into positions 0,1,...,n-3
    // After that, the last two must be in order
    for(int placed = 0; placed < n-2; placed++){
        // Find where value (placed+1) currently is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue; // already in place

        // Step 1: Move element from pos to position n-1 (last position)
        if(pos < n-1){
            // Operation: x = pos+1, y = n-1-pos
            // x+y = pos+1+n-1-pos = n, need x+y < n, so this doesn't work
            // Instead: x = pos, y = n-1-pos; x+y = n-1 < n. Need x>0 => pos>0
            if(pos > 0){
                // After op(pos, n-1-pos): suffix=p[pos+1..n-1], middle=p[pos..pos], prefix=p[0..pos-1]
                // Wait: x=pos, y=n-1-pos. middle is p[pos..n-1-(n-1-pos)-1] = p[pos..pos]. 
                // Result: p[pos+1..n-1] + p[pos] + p[0..pos-1]
                // Element at pos goes to position (n-1-pos) + 0 = n-1-pos... no.
                // suffix has n-1-pos elements, middle has 1 element, prefix has pos elements
                // element is at index pos, which is middle[0], goes to position (n-1-pos)
                // That's not n-1. Let me use a different approach.
                // Use x=1, y=n-1-pos to rotate element closer, or just do x=pos+1, y=n-1-pos-1 if valid
            }
            // Simpler: bring element to position 0 first, then to target
            // op(1, n-1-pos): moves p[pos+1..n-1] to front... no that's suffix of length n-1-pos
            // Let me just use: x=pos-placed, y=n-1-pos, need both>0 and sum<n
            // This brings suffix to front of active region... complex. Let me just brute force it.
            int x = pos+1, y = n-1-pos;
            if(y > 0 && x > 0 && x+y < n){ ops.push_back({x,y}); apply_op(p,x,y); }
            else if(pos > 0){ x=pos; y=n-1-pos; if(y>0&&x>0&&x+y<n){ ops.push_back({x,y}); apply_op(p,x,y); }}
            pos = -1; for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos==placed) continue;
        }
        // Step 2: element at some position, move to 'placed'
        if(pos != placed){
            int x = placed > 0 ? placed : 1, y = n - pos;
            if(x>0&&y>0&&x+y<n){ ops.push_back({x,y}); apply_op(p,x,y); }
            pos=-1; for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        }
        if(pos!=placed && (int)ops.size()<4*n-2){
            // Try all valid ops to find one that moves element to placed
            for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
                vector<int> tmp=p; apply_op(tmp,x,y);
                if(tmp[placed]==placed+1){ ops.push_back({x,y}); p=tmp; goto done; }
            }
            done:;
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
